def F(table, *names):
    return [f"{table}.{n}" for n in names]


def ALL(table, *exclude):
    t = next(x for x in TABLES if x[0] == table)
    return [f"{table}.{f['name']}" for f in t[3]
            if f["name"] not in ("Name", "SemanticTypeIri") and not f["name"].endswith("Id") and f["name"] not in exclude]


